std::string markdown_to_html(const std::string& markdown) {
    std::string html;
    std::stringstream ss(markdown);

    // Parse the markdown and convert it to html
    std::string line;
    while (std::getline(ss, line)) {
        // Replace markdown formatting with html tags
        std::regex regex("\\*(.*?)\\*"); // bold
        std::regex regex("\\_(.*?)\\_"); // italic
        std::regex regex("\\[(.*?)\\](.*?)"); // link
        std::regex regex("\\!(.*?)\\!"); // image
        std::regex regex("\\`(.*?)\\`"); // code
        std::regex regex("\\~(.*?)\\~"); // strikethrough
        std::regex regex("\\`(.*?)\\`"); // code
        std::regex regex("\\`(.*?)\\`"); // code
        std::regex regex("\\`(.*?)\\`"); // code

        std::string new_line = line;
        std::regex_replace(new_line, regex, "<b>$1</b>");
        std::regex_replace(new_line, regex, "<i>$1</i>");
        std::regex_replace(new_line, regex, "<a href=\"$2\">$1</a>");
        std::regex_replace(new_line, regex, "<img src=\"$1\" alt=\"$1\">");
        std::regex_replace(new_line, regex, "<code>$1</code>");
        std::regex_replace(new_line, regex, "<s>$1</s>");
        std::regex_replace(new_line, regex, "<code>$1</code>");
        std::regex_replace(new_line, regex, "<code>$1</code>");
        std::regex_replace(new_line, regex, "<code>$1</code>");

        html += new_line + "\n";
